entries[127115] = { ["name"] = "Lord Blastington's Scope of Doom", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (18), Primordial Ruby (2), Spirit of Harmony\nProfession Trainer:\nPandaria Engineering (35)\nCost:\n1\n30\n\nLord Blastington's Scope of Doom\nUse: Permanently attaches Lord Blastington's special scope to a ranged weapon, sometimes increasing Agility by 47 for 10 sec when dealing damage with ranged attacks.\n\nAttaching this scope to a ranged weapon causes it to become soulbound. Cannot be applied to items higher than level 320.\n32" }
entries[127116] = { ["name"] = "Mirror Scope", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (4), Lapis Lazuli (2)\nProfession Trainer:\nPandaria Engineering (1)\nCost:\n10\n\nMirror Scope\nUse: Permanently attaches a mirrored scope to a ranged weapon, sometimes increases Critical Strike by 34 for 10 sec when dealing damage with ranged attacks.\n\nAttaching this scope to a ranged weapon causes it to become soulbound. Cannot be applied to items higher than level 320.\n32" }
