entries[127124] = { ["name"] = "Locksmith's Powderkeg", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nReagents:\nSimple Wood , High-Explosive Gunpowder\nProfession Trainer:\nPandaria Engineering (1)\nCost:\n10\n\nUse: Blasts open locked doors and chests that require lockpicking skill of 35 and below.\nRequires Pandaria Engineering\n(1)" }
entries[127127] = { ["name"] = "G91 Landshark", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (2), High-Explosive Gunpowder (2)\nProfession Trainer:\nPandaria Engineering (1)\nCost:\n10\n\n(3)\nUse: Inflicts 688 Fire damage to an enemy up to 45 yards away, as well as any enemies within 10 yards of the primary target. (1 Min Cooldown)\n32" }
entries[127128] = { ["name"] = "Goblin Dragon Gun, Mark II", ["text"] = "3 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (3), High-Explosive Gunpowder (8)\nProfession Trainer:\nPandaria Engineering (25)\nCost:\n1\n\nUse: Unleash a gout of lightning, dealing 48 Nature damage to targets in a 10 yard cone in front of the caster every 0.5 sec for 4 sec.\n\nMay walk while casting. (30 Sec Cooldown)\n50 Charges\n32" }
entries[127129] = { ["name"] = "Blingtron 4000", ["text"] = "2 sec cast\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nLiving Steel (4), Trillium Bar (4), Ghost Iron Bar (4), Vermilion Onyx (4), Wild Jade (4), Spirit of Harmony (4)\nProfession Trainer:\nPandaria Engineering (75)\nCost:\n3\n50\n\nBlingtron 4000\nBinds when picked up\nToy\nUse: Assembles the incredible Blingtron 4000, a robot of infinite wealth. Bling, as he likes to be called, will give out a random gift to anyone who talks to him, but only once per day. Lasts 10 min. (4 Hrs Cooldown)\nRequires Pandaria Engineering\n(75)" }
entries[127130] = { ["name"] = "Mist-Piercing Goggles", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (8), Spirit of Harmony (2)\nProfession Trainer:\nPandaria Engineering (1)\nCost:\n10\n\nMist-Piercing Goggles\nBinds when equipped\nHead\nEquip: Allows you to see additional mining nodes and herbs while in Pandaria.\n\"While these goggles are very fashionable, they don't need to be worn to receive their special benefit.\"" }
entries[127131] = { ["name"] = "Thermal Anvil", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nHigh-Explosive Gunpowder (8), Ghost Iron Bolts (6)\nProfession Trainer:\nPandaria Engineering (25)\nCost:\n1\n\nUse: Places a Thermal Anvil at your feet, granting anyone nearby the use of both an anvil and a forge. Lasts 5 min. (5 Min Cooldown)\n20 Charges" }
entries[127132] = { ["name"] = "Wormhole Generator: Pandaria", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nTrillium Bar (12), Spirit of Harmony (2)\nProfession Trainer:\nPandaria Engineering (45)\nCost:\n1\n75\n\nWormhole Generator: Pandaria\nBinds when used\nToy\nUse: Teleports you to somewhere in Pandaria. The exact location is difficult to predict, but will likely be far away. (15 Min Cooldown)\n29\nRequires Pandaria Engineering\n(1)\n\"There is a tiny note on the side: Wheeeeeeeeeee!\"" }
entries[127134] = { ["name"] = "Ghost Iron Dragonling", ["text"] = "2 sec cast\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nWindwool Cloth (12), Ghost Iron Bolts (8), High-Explosive Gunpowder (4)\nOptional Reagents:\nOptional Reagent Slot (#49)\nProfession Trainer:\nPandaria Engineering (25)\nCost:\n1\n\nGhost Iron Dragonling\nBinds when equipped\nUnique-EquippedTrinket\nCogwheel Socket\nCogwheel Socket\nCogwheel Socket\n\nEquip: Your attacks have a chance to summon a Ghost Iron Dragonling to fight with you for 20 sec. (Proc chance: 25%, 1m cooldown)\n33" }
entries[127135] = { ["name"] = "Mechanical Pandaren Dragonling", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bar (4), Trillium Bar (6), Spirit of Harmony (2)\nProfession Trainer:\nPandaria Engineering (50)\nCost:\n2\n\nMechanical Pandaren Dragonling\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your whelpling.\n1 to 80 ( 80)" }
entries[127136] = { ["name"] = "Big Game Hunter", ["text"] = "3 sec cast\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (12), Hair Trigger , Walnut Stock , Mirror Scope\nOptional Reagents:\nOptional Reagent Slot (#49)\nProfession Trainer:\nPandaria Engineering (1)\nCost:\n10\n\nBig Game Hunter\nBinds when equipped\nRanged Gun\n6 - 12 Damage Speed 3.00\n(3.0 damage per second)\n+3 Agility\n+6 Stamina\n+ 4 Critical Strike\n+ 2 Haste\n\nPrismatic Socket\nSocket Bonus: + 1 Agility\n\nDurability 100 / 100\n32" }
entries[127137] = { ["name"] = "Long-Range Trillium Sniper", ["text"] = "3 sec cast\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nTrillium Bar (12), Hair Trigger , Spirit of Harmony , Lord Blastington's Scope of Doom\nProfession Trainer:\nPandaria Engineering (40)\nCost:\n1\n50\n\nLong-Range Trillium Sniper\nBinds when equipped\nRanged Gun\n6 - 12 Damage Speed 3.00\n(3.0 damage per second)\n+3 Agility\n+6 Stamina\n+ 3 Critical Strike\n+ 4 Haste\n\nPrismatic Socket\nSocket Bonus: + 0 Agility\n\nDurability 100 / 100\n35" }
entries[127138] = { ["name"] = "Depleted-Kyparium Rocket", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nLiving Steel (12), Kyparite (200), Orb of Mystery (3), High-Explosive Gunpowder (12), Spirit of Harmony (12), Ghost Iron Bolts (20)\nProfession Trainer:\nPandaria Engineering (75)\nCost:\n3\n50\n\nDepleted-Kyparium Rocket\nUnique\nMount (Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nThe apex of goblin ingenuity! This mount changes depending on your Riding skill and location.\n1 to 80 ( 80)\nRequires\n\n\"When Kyparite is depleted of its amber essence it becomes fairly resistant to the corrosion from rocket fuel.\"\nProfession:\nEngineering" }
entries[127139] = { ["name"] = "Geosynchronous World Spinner", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nLiving Steel (12), Trillium Bar (12), Spirit of Harmony (12), Ghost Iron Bolts (20), Orb of Mystery (3)\nProfession Trainer:\nPandaria Engineering (75)\nCost:\n3\n50\n\nGeosynchronous World Spinner\nUnique\nMount (Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nA device that rotates the very world beneath you! This mount changes depending on your Riding skill and location.\n1 to 80 ( 80)\nRequires\n\n\"This rocket was originally designed to speed up the rotation of the world making for shorter nights. Gnomes with insomnia can have lofty goals.\"\nProfession:\nEngineering" }
