entries[127164] = { ["name"] = "Heavenly Golden Cloud Serpent", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Heavenly Golden Cloud Serpent. This is a flying mount.\n\"Warmth and hope emanate from this great creature, which glows like a sunrise over the mountains.\"\nVendor:\nMistweaver Ku\nZone:\nTimeless Isle\nEmperor Shaohao - Exalted" }
